import React, { useEffect, useState } from "react";
import axios from "axios";
import "../styles/main.css";
import { getApplicableFeeKeys } from "../utils/feeRules";

export default function ParentFeePage() {
  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(true);
  const [paying, setPaying] = useState(false);

  useEffect(() => {
    const fetchSummary = async () => {
      try {
        const token = localStorage.getItem("token");
        const res = await axios.get("http://localhost:5000/api/parent/fee-summary", {
          headers: { Authorization: `Bearer ${token}` },
        });
        setSummary(res.data);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    };
    fetchSummary();
  }, []);

  const handlePay = async () => {
    try {
      setPaying(true);
      const token = localStorage.getItem("token");
      await axios.post(
        "http://localhost:5000/api/parent/pay-fee",
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      alert("Payment successful!");
    } catch (err) {
      console.error(err);
      alert("Payment failed. Try again.");
    } finally {
      setPaying(false);
    }
  };

  if (loading) return <p>Loading...</p>;
  if (!summary) return <p>No data available</p>;

  const applicableKeys = getApplicableFeeKeys(summary.student?.className || "");

  return (
    <div className="parent-fee-page">
      <h2>Fee Summary for {summary.student?.name}</h2>
      <p>
        <b>Class:</b> {summary.student?.className}
      </p>

      <table className="fee-table">
        <thead>
          <tr>
            <th>Fee Type</th>
            <th>Amount (₹)</th>
          </tr>
        </thead>
        <tbody>
          {applicableKeys.map((key) => (
            <tr key={key}>
              <td>{summary.fee.items[key]?.title || key}</td>
              <td>₹{summary.fee.items[key]?.amount || 0}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <h3>Total: ₹{summary.fee.total}</h3>

      <button
        className="pay-btn"
        onClick={handlePay}
        disabled={paying}
      >
        {paying ? "Processing..." : "Pay Fee"}
      </button>
    </div>
  );
}













